mapper.select:
SELECT * FROM `wms_picking_approve` WHERE bool_delete_enum = 0
and serial_number like concat('%',#{param.serialNumber},'%')
and task_order_numbers like concat('%',#{param.taskOrderNumber},'%')
and create_time between #{param.createTimeList[0]} and #{param.createTimeList[1]}
and application_name like concat('%',#{param.applicationName},'%')
and review_status = #{param.reviewStatus}

SELECT wmod.basic_class basicClass, wmod.thickness thickness, wmod.specification specification, sum(wmod.mete) meteCount FROM wms_move_outbound_detail wmod WHERE EXISTS ( SELECT 1 FROM wms_picking_approve_detail wpad INNER JOIN wms_picking_approve wpa ON wpa.id = wpad.picking_approve_id AND wpa.review_status = 2 INNER JOIN wms_picking_detail wpd ON wpad.picking_detail_id = wpd.id AND wpd.bool_delete_enum = 0 INNER JOIN wms_picking wp ON wpd.picking_id = wp.id AND wp.bool_delete_enum = 0
and wp.project_id = #{projectId}
and wp.mes_workshop_id = #{workShopId}
WHERE wmod.id = wpad.out_detail_id ) AND wmod.bool_delete_enum = 0 AND wmod.basic_class = 1 group by wmod.basic_class,wmod.thickness,wmod.specification

SELECT wmod.basic_class basicClass, wmod.specification specification, sum(wmod.mete) meteCount FROM wms_move_outbound_detail wmod WHERE EXISTS ( SELECT 1 FROM wms_picking_approve_detail wpad INNER JOIN wms_picking_approve wpa ON wpa.id = wpad.picking_approve_id AND wpa.review_status = 2 INNER JOIN wms_picking_detail wpd ON wpad.picking_detail_id = wpd.id AND wpd.bool_delete_enum = 0 INNER JOIN wms_picking wp ON wpd.picking_id = wp.id AND wp.bool_delete_enum = 0
and wp.project_id = #{projectId}
and wp.mes_workshop_id = #{workShopId}
WHERE wmod.id = wpad.out_detail_id ) AND wmod.bool_delete_enum = 0 AND wmod.basic_class = 2 group by wmod.basic_class,wmod.specification
